// Dünün metriklerini ve 7 günlük baz çizgisini hazırla + kural tabanlı anomali tespiti
const days = $input.first().json;
const y = days[days.length - 1];
const win = days.slice(-8, -1);
const avg = (f) => win.reduce((a, d) => a + f(d), 0) / win.length;

const anomalies = [];
for (const v of Object.keys(y.verticals)) {
  const base = avg((d) => d.verticals[v].cancel_rate);
  if (y.verticals[v].cancel_rate > base * 1.8) {
    anomalies.push({ type: 'cancel_spike', vertical: v, value: y.verticals[v].cancel_rate, baseline: base });
  }
}
const pe = y.cancel_reasons.payment_error / Object.values(y.cancel_reasons).reduce((a,b)=>a+b,0);
if (pe > 0.35) anomalies.push({ type: 'payment_errors', share: pe, baseline: 0.15 });

return [{ json: { yesterday: y, baseline_7d: { gmv: avg(d => Object.values(d.verticals).reduce((a,x)=>a+x.gmv,0)) }, anomalies } }];

